SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'at',clock_timestamp(),
'fase162Present',to_regprocedure('public.routine_inventory_operation(uuid,uuid,text,jsonb)') IS NOT NULL,
'receiptsCreated', (SELECT count(*) FROM public.routine_inventory_operations),
'legacyTableCount',jsonb_array_length(o.j->'tables')=jsonb_array_length(e.j->'tables'),
'legacyFunctionCount',jsonb_array_length(o.j->'functions')=jsonb_array_length(e.j->'functions'),
'legacyFunctionsAndACL',(SELECT bool_and((a-'definition_md5')=(b-'definition_md5') AND (a->>'signature'='apply_inventory_unit_event()' OR a->'definition_md5'=b->'definition_md5')) FROM jsonb_array_elements(o.j->'functions') a JOIN jsonb_array_elements(e.j->'functions') b ON a->>'signature'=b->>'signature'),
'legacyTablesRLSAndACL',(SELECT bool_and(a->'rls'=b->'rls' AND a->'force'=b->'force' AND a->'acl'=b->'acl') FROM jsonb_array_elements(o.j->'tables') a JOIN jsonb_array_elements(e.j->'tables') b ON a->>'name'=b->>'name'),
'legacyPolicies',(SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_array_elements(o.j->'policies')v)=(SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_array_elements(e.j->'policies')v),
'legacyColumns',(SELECT bool_and(EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(a->'columns','null'::jsonb),'[]'::jsonb)) av WHERE av=bv)) FROM jsonb_array_elements(o.j->'tables') a JOIN jsonb_array_elements(e.j->'tables') b ON a->>'name'=b->>'name' CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(b->'columns','null'::jsonb),'[]'::jsonb)) bv),'legacyConstraints',(SELECT bool_and(EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(a->'constraints','null'::jsonb),'[]'::jsonb)) av WHERE av=bv)) FROM jsonb_array_elements(o.j->'tables') a JOIN jsonb_array_elements(e.j->'tables') b ON a->>'name'=b->>'name' CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(b->'constraints','null'::jsonb),'[]'::jsonb)) bv),'legacyIndexes',(SELECT bool_and(EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(a->'indexes','null'::jsonb),'[]'::jsonb)) av WHERE av=bv)) FROM jsonb_array_elements(o.j->'tables') a JOIN jsonb_array_elements(e.j->'tables') b ON a->>'name'=b->>'name' CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(b->'indexes','null'::jsonb),'[]'::jsonb)) bv),'legacyTriggers',(SELECT bool_and(EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(a->'triggers','null'::jsonb),'[]'::jsonb)) av WHERE av=bv)) FROM jsonb_array_elements(o.j->'tables') a JOIN jsonb_array_elements(e.j->'tables') b ON a->>'name'=b->>'name' CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(b->'triggers','null'::jsonb),'[]'::jsonb)) bv)
) FROM observed o CROSS JOIN expected e;